#!/usr/bin/env node
/**
 * ROLE-MATRIX-DEPLOYMENT-GATE-01 (Gate 8) — automated role × endpoint authz sweep.
 *
 * Catches the scariest deployability class: "the UI hides it but the API allows it."
 * Signs in as each staff role + unauthenticated, fires a CURATED, SAFE probe set
 * (reads + denied-path writes only — no external side-effects, no real mutations on allow paths),
 * and asserts each probe's HTTP status matches the expected class for that role.
 *
 * Probes come from role-matrix-probes.json (generated by the role-matrix-authz-map workflow).
 * Roles: admin / supervisor / employee / unauth (+ client if a portal token is available).
 * Read-only of product code; no commits; --write not required (probes are self-contained + safe).
 */
import { readFileSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";
import { createClient } from "@supabase/supabase-js";
import { createRunner, assertServerUp, API, SB_URL, SB_ANON } from "./_helpers.mjs";
import { ensureE2EUsers } from "../create-e2e-users.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const PW = "BlueLeaf-E2E-2026!";

function classify(status) {
  if (status === 401) return "unauth";
  if (status === 403) return "forbidden";
  if ((status >= 200 && status < 300) || status === 400 || status === 404 || status === 422) return "allow";
  return `other(${status})`;
}

async function tokenFor(email) {
  const sb = createClient(SB_URL, SB_ANON, { auth: { autoRefreshToken: false, persistSession: false } });
  const { data } = await sb.auth.signInWithPassword({ email, password: PW });
  return data?.session?.access_token || null;
}

const run = createRunner();
run.section("ROLE-MATRIX-DEPLOYMENT-GATE-01 (Gate 8) — role × endpoint authz sweep");
if (!(await assertServerUp(run))) process.exit(1);

let probes;
try { probes = JSON.parse(readFileSync(join(HERE, "role-matrix-probes.json"), "utf8")); }
catch (e) { run.fail("load role-matrix-probes.json", e.message); process.exit(1); }

let tokens = { unauth: null, client: null };
try {
  const u = await ensureE2EUsers();
  tokens.admin = await tokenFor(u.admin?.email || "e2e-admin@blueleafbuilding.test");
  tokens.supervisor = await tokenFor(u.supervisor?.email || "e2e-supervisor@blueleafbuilding.test");
  tokens.employee = await tokenFor(u.employee?.email || "e2e-employee@blueleafbuilding.test");
} catch (e) { run.fail("auth setup", e.message); process.exit(1); }

const haveRole = (r) => r === "unauth" || !!tokens[r];
const counts = {}; // per module
const violations = []; // API-allows-but-should-deny

for (const p of probes) {
  const role = p.role;
  if (!haveRole(role)) { run.gap(`${p.module} ${p.method} ${p.path} [${role}]`, `no token for role ${role}`); continue; }
  const headers = { "Content-Type": "application/json" };
  if (tokens[role]) headers.Authorization = "Bearer " + tokens[role];
  let status = 0;
  try {
    const r = await fetch(API + p.path, {
      method: p.method,
      headers,
      body: ["POST", "PATCH", "PUT", "DELETE"].includes(p.method) ? "{}" : undefined,
    });
    status = r.status;
  } catch (e) { run.fail(`${p.method} ${p.path} [${role}]`, "fetch error: " + e.message); continue; }

  const got = classify(status);
  const want = p.expectedStatusClass;
  counts[p.module] = counts[p.module] || { pass: 0, fail: 0 };
  const label = `${p.module} ${p.method} ${p.path} [${role}] → ${status} (want ${want})`;
  if (got === want) { run.pass(label); counts[p.module].pass++; }
  else {
    run.fail(label, p.why || "");
    counts[p.module].fail++;
    // the dangerous class: expected forbidden/unauth but got allow
    if ((want === "forbidden" || want === "unauth") && got === "allow") {
      violations.push({ ...p, status, got });
    }
  }
}

const s = run.stats;
console.log("\n── Per-module ──────────────────────────────────────────────");
for (const [m, c] of Object.entries(counts)) console.log(`  ${m}: ${c.pass} pass / ${c.fail} fail`);
if (violations.length) {
  console.log("\n⚠️  API-ALLOWS-BUT-SHOULD-DENY (deployment blockers):");
  for (const v of violations) console.log(`  • ${v.module} ${v.method} ${v.path} [${v.role}] returned ${v.status} (expected ${v.expectedStatusClass})`);
}
console.log(`\n  Passed: ${s.passed}  Failed: ${s.failed}  Gap: ${s.gapDocumented}  | probes: ${probes.length}`);
if (s.failures?.length) s.failures.slice(0, 30).forEach((f) => console.log(`   • ${f.name}: ${f.reason}`));
process.exit(s.failed > 0 ? 1 : 0);
